//! The truncation length is configured through the
//! `POLARS_PARQUET_BINARY_STATISTICS_TRUNCATE_LEN` environment variable and
//! defaults to [`DEFAULT_TRUNCATE_LEN`]. A value of `0` disables truncation, in
//! which case the exact min/max values are stored regardless of their length.

/// The default number of bytes to which string/binary statistics are truncated.
const DEFAULT_TRUNCATE_LEN: usize = 64;

/// Returns the configured truncation length.
///
/// * `None` means truncation is disabled (the environment variable is set to `0`).
/// * `Some(n)` means statistics should be truncated to at most `n` bytes.
///
/// The environment variable is read on every call so that it can be toggled at
/// runtime (this is not on a hot path). An unset or unparseable value falls back
/// to [`DEFAULT_TRUNCATE_LEN`].
fn statistics_truncate_len() -> Option<usize> {
    let len = std::env::var("POLARS_PARQUET_BINARY_STATISTICS_TRUNCATE_LEN")
        .ok()
        .and_then(|v| v.parse::<usize>().ok())
        .unwrap_or(DEFAULT_TRUNCATE_LEN);
    (len != 0).then_some(len)
}

