///
/// This is the length of the longest valid UTF-8 prefix of `s` that fits within
/// `limit` bytes.
fn floor_char_boundary(s: &str, limit: usize) -> usize {
    if limit >= s.len() {
        return s.len();
    }
    // `is_char_boundary(0)` is always `true`, so this always finds a value.
    (0..=limit).rev().find(|&i| s.is_char_boundary(i)).unwrap_or(0)
