    // Every byte within the limit is `0xFF`; extend the search to find the first
    // byte that can be incremented.
    for i in limit..value.len() {
        if value[i] != u8::MAX {
            let mut result = value[..=i].to_vec();
            result[i] += 1;
            return Some(result);
        }
