//!
//! Storing the exact minimum and maximum values in the column statistics can blow
//! up the size of a Parquet file when a column contains very large values (e.g. a
//! single multi-megabyte string). To avoid this, the min/max bounds are truncated
//! to a small number of bytes while still remaining valid bounds:
//! * the truncated *minimum* is a prefix of the original value (`<= min`), and
//! * the truncated *maximum* is a prefix of the original value with its tail
//!   incremented so that it stays `>= max`.
//!
//! The truncation length is configured through the
//! `POLARS_PARQUET_BINARY_STATISTICS_TRUNCATE_LEN` environment variable and
//! defaults to [`DEFAULT_TRUNCATE_LEN`]. A value of `0` disables truncation, in
//! which case the exact min/max values are stored regardless of their length.

/// The default number of bytes to which string/binary statistics are truncated.
const DEFAULT_TRUNCATE_LEN: usize = 64;

/// Returns the configured truncation length.
///
/// * `None` means truncation is disabled (the environment variable is set to `0`).
/// * `Some(n)` means statistics should be truncated to at most `n` bytes.
///
/// The environment variable is read on every call so that it can be toggled at
/// runtime (this is not on a hot path). An unset or unparseable value falls back
/// to [`DEFAULT_TRUNCATE_LEN`].
fn statistics_truncate_len() -> Option<usize> {
    let len = std::env::var("POLARS_PARQUET_BINARY_STATISTICS_TRUNCATE_LEN")
        .ok()
        .and_then(|v| v.parse::<usize>().ok())
        .unwrap_or(DEFAULT_TRUNCATE_LEN);
    (len != 0).then_some(len)
}

/// Returns the largest index `<= limit` that lies on a `char` boundary of `s`.
///
/// This is the length of the longest valid UTF-8 prefix of `s` that fits within
/// `limit` bytes.
fn floor_char_boundary(s: &str, limit: usize) -> usize {
    if limit >= s.len() {
        return s.len();
    }
    // `is_char_boundary(0)` is always `true`, so this always finds a value.
    (0..=limit).rev().find(|&i| s.is_char_boundary(i)).unwrap_or(0)
}

/// Truncates the *minimum* statistic `value` to the configured length.
///
/// For UTF-8 values (`is_utf8`) the result is the longest valid UTF-8 prefix that
/// fits within the byte limit (so it never splits a multi-byte character). For
/// binary values the truncation happens at the raw byte level.
///
/// Values that already fit within the limit are returned unchanged.
pub(crate) fn truncate_min_value(value: &[u8], is_utf8: bool) -> Vec<u8> {
