        Some(limit) if value.len() > limit => {
            if is_utf8 {
                // SAFETY: `is_utf8` guarantees `value` is valid UTF-8.
                let s = unsafe { std::str::from_utf8_unchecked(value) };
                let split = floor_char_boundary(s, limit);
                value[..split].to_vec()
            } else {
                value[..limit].to_vec()
            }
        },
        _ => value.to_vec(),
    }
}

/// Truncates the *maximum* statistic `value` to the configured length, producing a
